#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static char *inbuf;
static size_t inpos, inlen;

static inline int readInt(void) {
    while (inpos < inlen && (inbuf[inpos] < '0' || inbuf[inpos] > '9')) inpos++;
    int x = 0;
    while (inpos < inlen && inbuf[inpos] >= '0' && inbuf[inpos] <= '9')
        x = x * 10 + (inbuf[inpos++] - '0');
    return x;
}

static int cmpkey(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    /* read all of stdin */
    size_t cap = 1u << 22, len = 0;
    inbuf = (char *)malloc(cap);
    for (;;) {
        if (len == cap) {
            cap <<= 1;
            inbuf = (char *)realloc(inbuf, cap);
        }
        size_t r = fread(inbuf + len, 1, cap - len, stdin);
        if (r == 0) break;
        len += r;
    }
    inlen = len;
    inpos = 0;

    int N = readInt();
    int M = readInt();
    long total = 2L * (long)M;

    uint64_t *keys = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(total > 0 ? total : 1));
    int *off = (int *)calloc((size_t)N + 2, sizeof(int));
    for (int i = 0; i < M; i++) {
        int a = readInt();
        int b = readInt();
        keys[2 * i]     = ((uint64_t)a << 17) | (uint64_t)b;
        keys[2 * i + 1] = ((uint64_t)b << 17) | (uint64_t)a;
        off[a + 1]++;
        off[b + 1]++;
    }
    for (int u = 1; u <= N; u++) off[u + 1] += off[u];

    qsort(keys, (size_t)total, sizeof(uint64_t), cmpkey);

    int *adj = (int *)malloc(sizeof(int) * (size_t)(total > 0 ? total : 1));
    int *pos = (int *)malloc(sizeof(int) * ((size_t)N + 2));
    memcpy(pos, off, sizeof(int) * ((size_t)N + 2));
    for (long i = 0; i < total; i++) {
        int u = (int)(keys[i] >> 17);
        int v = (int)(keys[i] & ((1u << 17) - 1));
        adj[pos[u]++] = v;
    }

    /*
     * DP over states (last odd vertex o, last even vertex e):
     *   G(o,e) = max continuation when next must place an ODD vertex u in adj(e), u > o
     *   F(o,e) = max continuation when next must place an EVEN vertex w in adj(o), w > e
     * G(o,e) = 1 + max_{u in adj(e), u>o} F(u,e);  F(o,e) = 1 + max_{w in adj(o), w>e} G(o,w)
     * Process u = N..1; for each e in adj(u) (decreasing): G from Rmax[e] (holds max F(u',e), u'>u),
     * F from running max S of G(u,w) for w > e; then push F(u,e) into Rmax[e], G(u,e) into S.
     */
    int *Rmax = (int *)malloc(sizeof(int) * ((size_t)N + 2));
    int *ans = (int *)malloc(sizeof(int) * ((size_t)N + 2));
    for (int i = 0; i <= N + 1; i++) Rmax[i] = -1;

    for (int u = N; u >= 1; u--) {
        int S = -1, maxG = -1;
        int lo = off[u], hi = off[u + 1];
        for (int i = hi - 1; i >= lo; i--) {
            int e = adj[i];
            int R = Rmax[e];
            int Gv = (R < 0) ? 0 : R + 1;
            int Fv = (S < 0) ? 0 : S + 1;
            if (Fv > R) Rmax[e] = Fv;      /* F(u,e) available for later (smaller) o */
            if (Gv > S) S = Gv;            /* G(u,e) usable for F(u,e') with e' < e */
            if (Gv > maxG) maxG = Gv;
        }
        ans[u] = (maxG < 0) ? 1 : maxG + 2; /* c + first even + best continuation */
    }

    char *out = (char *)malloc((size_t)N * 8 + 16);
    size_t op = 0;
    for (int u = 1; u <= N; u++) {
        if (u > 1) out[op++] = ' ';
        int x = ans[u];
        char tmp[12];
        int tl = 0;
        do {
            tmp[tl++] = (char)('0' + x % 10);
            x /= 10;
        } while (x > 0);
        while (tl > 0) out[op++] = tmp[--tl];
    }
    out[op++] = '\n';
    fwrite(out, 1, op, stdout);
    return 0;
}
